for T, txt in B.items():
    p = ROOT / 'targets' / T / 'NOTES.md'
    t = p.read_text(encoding='utf8')
    if 'v6 spelling check' in t:
        continue
    block = H + txt + '\n\n'
    i = t.find('\n## Remaining gaps')
    t = (t[:i + 1] + block + t[i + 1:]) if i >= 0 else (t.rstrip('\n') + '\n\n' + block.rstrip('\n') + '\n')
    p.write_text(t, encoding='utf8'); print(T)
